const state = {
  screen: 'onboarding', sheet: null, toast: '', day: 0, rotation: 0,
  goal: ['Easier meals'], pattern: 'Omnivore', health: [], allergies: [],
  otherGoal: '', otherAllergy: '', otherHealth: '', otherCuisine: '',
  neverEat: '', mealsToPlan: 'Breakfast, lunch & dinner', pantryChanged: false,
  budgetAmount: 2000, timeMinutes: 30, cuisines: ['Indian'], notificationTime: 'Evening',
  consent: false, planAccepted: false, planInputsChanged: false, selectedMerchant: 0, selectedPrepared: 0, notifications: true,
  pausedFacts: [], notificationCategories: ['Plan ready','Pantry check','Meal check-in'], notificationFrequency: 'Daily', quietStart: '22:00', quietEnd: '07:00',
  meals: {
    breakfast: ['Yogurt, banana & oats', 'Tomato & basil toast', 'Egg toast & fruit', 'Apple & cinnamon oats', 'Avocado toast & tomatoes'],
    lunch: ['Chickpea rice bowl', 'Tomato pasta & greens', 'Paneer wrap & salad', 'Lentil salad & flatbread', 'Vegetable quinoa bowl'],
    dinner: ['One-pan veggie khichdi', 'Quick pesto pasta', 'Vegetable noodles & tofu', 'Chickpea tomato stew', 'Roasted vegetables & couscous']
  },
  chatView: 'plan', chatRequest: '', chatTurns: [], pantryIndex: null, removedMeals: [], servings: {breakfast:1,lunch:1,dinner:1}, pantry: [{name:'Rice',qty:'~1 kg',icon:'🍚'},{name:'Chickpeas',qty:'1 can',icon:'🫘'},{name:'Onion',qty:'2 left',icon:'🧅'}],
  consumed: [], logMealName: '', mealOffsets: {}, dayDrafts: {}, factSources: {}
};
const $ = s => document.querySelector(s);
const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const chip = (label, cls='') => `<span class="pill ${cls}">${label}</span>`;
const choice = (group,value,active) => `<button class="choice ${active?'selected':''}" data-action="choice" data-group="${group}" data-value="${esc(value)}" aria-pressed="${active}"><span class="check">${active?'✓':''}</span>${esc(value)}</button>`;
const choices = (group,items,selected) => `<div class="choice-grid">${items.map(x=>choice(group,x,selected.includes(x))).join('')}</div>`;
const detailField = (field,label,placeholder) => `<label class="field-label" for="${field}">${label}</label><input class="input" id="${field}" data-field="${field}" value="${esc(state[field])}" placeholder="${esc(placeholder)}"/>`;
const otherField = (group,field,label,placeholder) => state[group].includes('Other') ? detailField(field,label,placeholder) : '';
const selectedWithOther = (group,field) => state[group].map(x => x==='Other' && state[field].trim() ? `Other: ${state[field].trim()}` : x).join(', ');
const rupees = amount => `₹${new Intl.NumberFormat('en-IN').format(amount)}`;
const plannedTypes = () => state.mealsToPlan==='Dinner only'?['dinner']:state.mealsToPlan==='Lunch & dinner'?['lunch','dinner']:['breakfast','lunch','dinner'];
const activeTypes = () => plannedTypes().filter(type=>!state.removedMeals.includes(type));
const mealLabel = type => type[0].toUpperCase()+type.slice(1);
const planDates = Array.from({length:5},(_,i)=>{const date=new Date();date.setDate(date.getDate()+i+1);return date});
const pantryChanged = () => { state.pantryChanged=true; state.planAccepted=false; };
const rangeControl = (key,label,min,max,step,value,display) => `<div class="range-control"><div class="range-heading"><label class="field-label" for="${key}">${label}</label><strong id="${key}-value">${display}</strong></div><input class="range-input" type="range" id="${key}" data-slider="${key}" min="${min}" max="${max}" step="${step}" value="${value}" style="--range-progress:${(value-min)/(max-min)*100}%"/><div class="range-limits"><span>${key==='budgetAmount'?rupees(min):`${min} min`}</span><span>${key==='budgetAmount'?rupees(max):`${max} min`}</span></div></div>`;
const header = (title,action='notifications') => `<header class="screen-header"><span class="wordmark">${title}</span><button class="icon-button" data-action="${action}" aria-label="${action}">${action==='notifications'?'♧':'⚙'}</button></header>`;
const nav = active => `<nav class="bottom-nav" aria-label="Main navigation">${[['chat','◉','Chat'],['plan','▦','Plan'],['insights','◫','Insights'],['you','♙','You']].map(([id,icon,label])=>`<button class="nav-item ${active===id?'active':''}" data-action="nav" data-screen="${id}" aria-label="${label}" aria-current="${active===id?'page':'false'}"><span class="nav-icon">${icon}</span>${label}</button>`).join('')}</nav>`;
const wrap = (content,active,classes='') => `<div class="screen ${classes}">${content}</div>${nav(active)}`;
const mealName = (type) => {
  const index=(state.rotation+state.day+(state.mealOffsets[type]||0))%5;
  if(state.pattern==='Vegan')return ({breakfast:['Fruit & oat bowl','Tomato & basil toast','Banana oat pancakes','Apple & cinnamon oats','Avocado toast & tomatoes'],lunch:['Chickpea rice bowl','Tomato pasta & greens','Hummus wrap & salad','Lentil salad & flatbread','Vegetable quinoa bowl'],dinner:['One-pan veggie khichdi','Tomato & bean pasta','Vegetable noodles & tofu','Chickpea tomato stew','Roasted vegetables & couscous']})[type][index];
  if(state.pattern==='Vegetarian'&&type==='breakfast'&&index===2)return 'Paneer toast & fruit';
  return state.meals[type][index];
};
const mealIngredients = type => ({
  'Yogurt, banana & oats':'Oats, yogurt, banana',
  'Fruit & oat bowl':'Oats, banana, seasonal fruit',
  'Tomato & basil toast':'Bread, tomato, basil',
  'Egg toast & fruit':'Eggs, bread, fruit',
  'Paneer toast & fruit':'Paneer, bread, fruit',
  'Banana oat pancakes':'Oats, banana, plant milk',
  'Chickpea rice bowl':'Rice, chickpeas, cucumber',
  'Tomato pasta & greens':'Pasta, tomato, leafy greens',
  'Paneer wrap & salad':'Paneer, flatbread, salad leaves',
  'Hummus wrap & salad':'Hummus, flatbread, salad leaves',
  'One-pan veggie khichdi':'Rice, lentils, vegetables',
  'Quick pesto pasta':'Pasta, basil pesto, vegetables',
  'Tomato & bean pasta':'Pasta, tomato, beans',
  'Vegetable noodles & tofu':'Noodles, tofu, vegetables',
  'Apple & cinnamon oats':'Oats, apple, cinnamon',
  'Avocado toast & tomatoes':'Bread, avocado, tomatoes',
  'Lentil salad & flatbread':'Lentils, cucumber, flatbread',
  'Vegetable quinoa bowl':'Quinoa, vegetables, chickpeas',
  'Chickpea tomato stew':'Chickpeas, tomato, onion',
  'Roasted vegetables & couscous':'Vegetables, couscous, olive oil'
})[mealName(type)] || 'Ingredient details need verification';
const draftIngredients = () => [...new Set(activeTypes().flatMap(type=>mealIngredients(type).split(',').map(x=>x.trim()).filter(Boolean)))];
const needsVerifiedRecipes = () => state.allergies.length > 0 || Boolean(state.neverEat.trim());
const pausedSafety = () => state.pausedFacts.some(x=>['allergies','health','neverEat'].includes(x.split(':')[0]));
const needsHealthReview = () => state.health.some(x=>x!=='None'&&x!=='Prefer not to say') || Boolean(state.otherHealth.trim());
const planningConstraint = () => state.allergies.length ? 'your reported allergy' : 'your personal food rules';
const planNeedsAdjustment = () => state.timeMinutes < 25 || state.budgetAmount < 640;
const basketNeedsRefresh = () => state.mealsToPlan!=='Breakfast, lunch & dinner' || state.pantryChanged || state.planInputsChanged || !state.pantry.some(x=>x.name.toLowerCase()==='rice') || state.removedMeals.length>0 || Object.values(state.servings).some(x=>x!==1) || Object.values(state.mealOffsets).some(x=>x!==0) || state.rotation!==0 || state.day!==0;
const basketRefreshReason = () => state.pantryChanged?'Your pantry changed. Review the updated ingredient checklist; a new price quote is needed.':state.mealsToPlan!=='Breakfast, lunch & dinner'?'Your selected meals need their own grocery quote.':state.removedMeals.length?'Removed meals need a new grocery estimate.':Object.values(state.servings).some(x=>x!==1)?'Serving changes need a new grocery estimate.':state.planInputsChanged?'Your updated preferences need a new plan and grocery estimate.':!state.pantry.some(x=>x.name.toLowerCase()==='rice')?'Rice is no longer listed in your pantry; the example grocery estimate needs recalculation.':'This meal or day differs from the example grocery estimate. A fresh basket is needed.';
const adjustmentReason = () => state.timeMinutes < 25 ? `The example draft takes about 25 minutes, above your ${state.timeMinutes}-minute limit.` : `The example grocery list is ₹640, above your ${rupees(state.budgetAmount)} weekly budget.`;

function onboarding(){return `<div class="screen onboarding"><div class="onboarding-top"><span class="wordmark">valora<span style="color:#a2c9ae">.</span></span>${chip('About 2 min')}</div><div class="eyebrow-small">GETTING TO KNOW YOU</div><h1 class="page-title" style="margin-top:8px">Let's make food feel easier.</h1>
  ${question(1,'What would you like help with?','Choose any that fit.',`${choices('goal',['Easier meals','More variety','Eat more protein','Steadier routine','Spend less','Other'],state.goal)}${otherField('goal','otherGoal','Tell us your goal','e.g. Less decision fatigue')}`)}
  ${question(2,'How do you usually eat?','The label is a starting point. Your own rules matter more.',`<div class="segmented">${['Omnivore','Vegetarian','Vegan'].map(x=>`<button data-action="single" data-group="pattern" data-value="${x}" class="${state.pattern===x?'active':''}">${x}</button>`).join('')}</div>${detailField('neverEat','Foods you don’t eat (optional)',state.pattern==='Vegan'?'e.g. soy, mushrooms, coconut':state.pattern==='Vegetarian'?'e.g. dairy, mushrooms':'e.g. beef, pork, chicken')}
  <p class="inline-note">Something you don’t like to eat.</p><label class="field-label" for="meals-select">Meals to plan</label><select class="input" id="meals-select">${['Breakfast, lunch & dinner','Lunch & dinner','Dinner only'].map(x=>`<option ${state.mealsToPlan===x?'selected':''}>${x}</option>`).join('')}</select>`)}
  ${question(3,'Any allergies?','Select any that apply.',`<label class="field-label">Allergies</label>${choices('allergies',['Peanuts','Tree nuts','Milk','Eggs','Wheat','Other'],state.allergies)}${otherField('allergies','otherAllergy','Which allergy?','e.g. sesame')}<label class="field-label">Current health context (optional)</label>${choices('health',['None','Diabetes','High blood pressure','Digestive issue','Recent injury','Other','Prefer not to say'],state.health)}${otherField('health','otherHealth','Tell us only what you want to share','e.g. a recent injury')}`)}
  ${question(4,'What makes a plan practical?','We’ll respect your time and spending limit.',`${rangeControl('budgetAmount','Weekly grocery budget',500,15000,250,state.budgetAmount,`${rupees(state.budgetAmount)} / week`)}${rangeControl('timeMinutes','Max cooking time per meal',5,120,5,state.timeMinutes,`${state.timeMinutes} min`)}`)}
  ${question(5,'What do you enjoy?','Pick a starting point. We’ll keep learning.',`${choices('cuisines',['Indian','Italian','Asian','Mediterranean','Mexican','Anything','Other'],state.cuisines)}${otherField('cuisines','otherCuisine','Which cuisine?','e.g. Korean')}<label class="field-label">When should we suggest your next plan?</label><div class="segmented">${['Morning','Evening'].map(x=>`<button data-action="single" data-group="notificationTime" data-value="${x}" class="${state.notificationTime===x?'active':''}">${x}</button>`).join('')}</div>`)}
  <label class="consent"><input type="checkbox" id="consent" ${state.consent?'checked':''}/><span>I understand Valora helps with everyday food planning. I’ll confirm important details before they shape my plan.</span></label><button class="primary full" data-action="finish-onboarding">See my profile summary →</button></div>`}
function question(n,title,desc,body){return `<section class="question"><div class="question-head"><span class="question-number">${n}</span><div><h3>${title}</h3><p>${desc}</p></div></div>${body}</section>`}
function profileRows(){return `${summaryRow('Goal',selectedWithOther('goal','otherGoal'))}${summaryRow('Eating pattern',state.pattern)}${summaryRow('Meals to plan',state.mealsToPlan)}${state.neverEat.trim()?summaryRow('Foods to avoid',state.neverEat.trim()):''}${summaryRow('Allergies',state.allergies.length?selectedWithOther('allergies','otherAllergy'):'None reported')}${summaryRow('Health context',state.health.length?selectedWithOther('health','otherHealth'):'Not shared')}${summaryRow('Weekly budget',`${rupees(state.budgetAmount)} / week`)}${summaryRow('Cooking time',`Up to ${state.timeMinutes} min`)}${summaryRow('Cuisines',selectedWithOther('cuisines','otherCuisine'))}${summaryRow('Planning time',state.notificationTime)}`}
function profileSummary(){return `<div class="screen onboarding">${header('Your starting profile','settings')}<h1 class="page-title">Does this look right?</h1><p class="subtext">This is what the agent will use for your first plan.</p><div style="height:17px"></div><div class="card">${profileRows()}</div><p class="inline-note" style="margin:18px 0">Safety details are based on what you reported. You can correct or remove them any time.</p><div class="button-row"><button class="secondary" data-action="back-onboarding">Edit answers</button><button class="primary" data-action="start-app">Looks right</button></div></div>`}
function summaryRow(k,v){return `<div class="list-row" style="justify-content:space-between"><strong>${k}</strong><small style="max-width:58%;text-align:right">${esc(v)}</small></div>`}
function chatWidget(){
  const origin = `<span class="source-tag">${state.chatRequest?'REQUEST RESULT':'IN FOCUS'}</span>`;
  if(state.chatView==='rationale'&&(pausedSafety()||needsVerifiedRecipes()||needsHealthReview()||planNeedsAdjustment()||basketNeedsRefresh()))state.chatView='plan';
  if(state.chatView==='pantry')return `<section class="focus-card card"><div class="focus-head">${origin}<span class="focus-source">Pantry estimate</span></div><h2>What you have</h2><p class="focus-copy">${state.pantry.length} items on your list. Adjust anything that has run out.</p>${state.pantry.map(x=>basketRow(x.icon,x.name,x.qty)).join('')}<button class="secondary full" data-action="pantry" style="margin-top:12px">Manage pantry</button></section>`;
  if(state.chatView==='allergies')return `<section class="focus-card card"><div class="focus-head">${origin}<span class="focus-source">Saved profile</span></div><h2>Your saved food details</h2><p class="focus-copy">${state.allergies.length?'Reported allergies':'No allergies recorded yet'}</p><div class="tag-wrap">${state.allergies.length?state.allergies.map(x=>chip(esc(x==='Other'&&state.otherAllergy?state.otherAllergy:x),'red')).join(''):chip('None recorded','soft')}</div><div class="focus-divider"></div><p class="focus-copy"><strong>Foods to avoid</strong><br>${state.neverEat.trim()?esc(state.neverEat):'None recorded'}</p><p class="focus-copy"><strong>Health context you shared</strong><br>${state.health.length?esc(selectedWithOther('health','otherHealth')):'Nothing shared'}</p><button class="secondary full" data-action="edit-profile">Review profile</button></section>`;
  if(state.chatView==='budget')return `<section class="focus-card card"><div class="focus-head">${origin}<span class="focus-source">Saved profile</span></div><h2>Your planning limits</h2><div class="focus-number">${rupees(state.budgetAmount)}<small>per week</small></div><p class="focus-copy">Up to ${state.timeMinutes} minutes of cooking per meal.</p><button class="secondary full" data-action="edit-profile">Change limits</button></section>`;
  if(state.chatView==='rationale')return `<section class="focus-card card"><div class="focus-head">${origin}<span class="focus-source">Plan context</span></div><h2>Why this draft?</h2><div class="reason-row"><span>01</span><p>${state.pantry.some(x=>x.name==='Rice')?'It uses rice already listed in your pantry.':'Rice is included in the grocery estimate because it is not listed in your pantry.'}</p></div><div class="reason-row"><span>02</span><p>The recipes are aimed at your ${state.timeMinutes}-minute cooking limit.</p></div><div class="reason-row"><span>03</span><p>Every meal remains editable before you make a shopping list.</p></div><p class="focus-footnote">This preview shows stored plan context. The live agent would check approved sources before adding nutrition guidance.</p><button class="primary full" data-action="chat-widget" data-value="plan">Show the plan</button></section>`;
  if(pausedSafety())return `<section class="focus-card card"><div class="focus-head">${origin}<span class="focus-source">Plan status</span></div><h2>Food detail paused</h2><p class="focus-copy">Review the paused detail before using a meal plan.</p><button class="primary full" data-action="memory">Review memory</button></section>`;
  if(needsVerifiedRecipes())return `<section class="focus-card card"><div class="focus-head">${origin}<span class="focus-source">Plan status</span></div><h2>Recipe check needed</h2><p class="focus-copy">We need verified ingredients to check ${planningConstraint()} before suggesting meals. Your pantry and saved profile are still available here.</p><div class="button-row"><button class="secondary" data-action="chat-widget" data-value="pantry">Pantry</button><button class="secondary" data-action="chat-widget" data-value="allergies">Food rules</button></div></section>`;
  if(needsHealthReview())return `<section class="focus-card card"><div class="focus-head">${origin}<span class="focus-source">Plan status</span></div><h2>Context check needed</h2><p class="focus-copy">You shared a health detail. This preview cannot check whether its example meals fit that context, so the draft is paused.</p><button class="secondary full" data-action="edit-profile">Review your details</button></section>`;
  if(planNeedsAdjustment())return `<section class="focus-card card"><div class="focus-head">${origin}<span class="focus-source">Plan status</span></div><h2>Draft needs an update</h2><p class="focus-copy">${adjustmentReason()} The full planner would find another option before asking you to accept it.</p><button class="secondary full" data-action="chat-widget" data-value="budget">View your limits</button></section>`;
  if(basketNeedsRefresh())return `<section class="focus-card card"><div class="focus-head">${origin}<span class="focus-source">Plan status</span></div><h2>Draft needs a refresh</h2><p class="focus-copy">Your meal or pantry changes affect the example grocery list. Review the draft before continuing.</p><button class="primary full" data-action="nav" data-screen="plan">Review draft</button></section>`;
  const mealCount=activeTypes().length;
  return `<section class="focus-card card"><div class="focus-head">${origin}<span class="focus-source">Ready draft</span></div><h2>Tomorrow's plan</h2><p class="focus-copy">${mealCount} ${mealCount===1?'meal':'meals'} in this draft. Pulled from your current plan.</p><div class="focus-meta">${chip('~25 min active','soft')}${state.pantry.some(x=>x.name==='Rice')?chip('Uses pantry rice','soft'):chip('Rice needed','soft')}</div>${plannedTypes().map(type=>miniMeal(mealLabel(type),mealName(type),({breakfast:'🥣',lunch:'🥗',dinner:'🍲'})[type])).join('')}<div class="button-row" style="margin-top:15px"><button class="secondary" data-action="chat-widget" data-value="rationale">Why these?</button><button class="primary" data-action="nav" data-screen="plan">Review plan</button></div></section>`;
}
function chatComposer(){return `<div class="composer"><div class="composer-field"><button class="composer-icon" data-action="voice" aria-label="Voice input" title="Voice input"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="9" y="3" width="6" height="12" rx="3"/><path d="M5.5 10.5a6.5 6.5 0 0 0 13 0M12 17v4m-4 0h8"/></svg></button><input id="chat-input" aria-label="Ask Valora" placeholder="Ask anything to Valora for your next plan..."/><button class="composer-icon attach" data-action="reports" aria-label="Attach a report or photo" title="Attach a report or photo"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m20 11.5-8.1 8.1a5 5 0 0 1-7.1-7.1l9.2-9.2a3.5 3.5 0 0 1 5 5l-9.2 9.2a2 2 0 0 1-2.8-2.8l8.5-8.5"/></svg></button><button class="send" data-action="send" aria-label="Send request" title="Send request"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg></button></div></div>`}
function chatConversation(){return wrap(`<header class="screen-header conversation-navbar"><button class="conversation-back" data-action="chat-home" aria-label="Back to your space">← <span>Your space</span></button><span class="wordmark">valora</span><button class="icon-button" data-action="notifications" aria-label="notifications">♧</button></header><div class="conversation-thread" aria-live="polite">${state.chatTurns.map(turn=>`<div class="conversation-turn"><span>YOU</span><p>${esc(turn)}</p></div>`).join('')}<div class="conversation-response"><span class="agent-avatar">V</span><div><strong>Valora</strong><p>Your message was received. This design preview has no live planning agent, so no calculation or saved detail has been changed.</p></div></div></div>`, 'chat','with-composer conversation-screen')+chatComposer()}
function chat(){
  if(state.chatView==='ask')return chatConversation();
  const preview=(kind,title,detail,icon)=>`<button class="glance-card" data-action="chat-widget" data-value="${kind}"><span class="glance-icon">${icon}</span><strong>${title}</strong><small>${detail}</small></button>`;
  const count=activeTypes().length;
  const planStatus=pausedSafety()?'Detail paused':needsVerifiedRecipes()?'Needs a recipe check':needsHealthReview()?'Needs a context check':planNeedsAdjustment()||basketNeedsRefresh()?'Needs an update':`${count} ${count===1?'meal':'meals'} ready`;
  return wrap(`${header('valora')}<div class="chat-intro"><span class="eyebrow-small">YOUR SPACE</span><h1>What do you need<br>right now?</h1><p>Open something you already have, or ask for a new thought.</p></div><div class="glance-grid">${preview('plan','Next plan',planStatus,'▦')}${preview('pantry','Pantry',`${state.pantry.length} items listed`,'◌')}${preview('allergies','Food rules',state.allergies.length?`${state.allergies.length} allergies saved`:'Your saved details','◇')}</div><div class="workspace-label"><span>${state.chatRequest?'YOUR REQUEST':'OPEN NOW'}</span><span>↘</span></div>${state.chatRequest?`<div class="request-card"><span class="request-mark">YOU ASKED</span><p>${esc(state.chatRequest)}</p></div>`:''}${chatWidget()}<div class="chat-suggest"><span class="eyebrow-small">TRY ASKING</span><div class="suggest-row"><button data-action="chat-prompt" data-value="What's in my pantry?">What's in my pantry?</button><button data-action="chat-prompt" data-value="Show my next plan">Show my next plan</button><button data-action="chat-prompt" data-value="What allergies do you have saved?">My allergies</button></div></div>`, 'chat','with-composer')+chatComposer()
}
function miniMeal(type,name,icon){const removed=state.removedMeals.includes(type.toLowerCase());return `<div class="meal-mini"><span class="food-icon">${removed?'＋':icon}</span><div><strong>${type}: ${removed?'Removed from draft':esc(name)}</strong><small>${removed?'Add another meal in Plan':`${state.servings[type.toLowerCase()]} ${state.servings[type.toLowerCase()]===1?'serving':'servings'} · adjust in Plan`}</small></div></div>`}
function planningHold(){
  const recipeCheck=needsVerifiedRecipes();
  const healthCheck=needsHealthReview();
  const title=recipeCheck?'Let’s verify recipes first.':healthCheck?'Context check needed.':'Draft needs an update';
  const copy=recipeCheck?'Your food rules need complete, verified ingredient data before meals or prepared food can be shown.':healthCheck?'You shared a health detail. This preview cannot verify how it affects the example meals.':adjustmentReason();
  return wrap(`${header('Your plan')}<h1 class="page-title">${title}</h1><p class="subtext">${copy}</p><div class="coverage-note"><strong>Planning paused</strong><p>${healthCheck?'Confirm relevant details before a suitable plan is proposed.':'Review your details or pantry while a suitable option is being checked.'}</p></div><div class="button-row"><button class="secondary" data-action="${recipeCheck||healthCheck?'profile-rules':'profile-practical'}">Review details</button><button class="primary" data-action="pantry">View pantry</button></div>`, 'plan');
}
function mealCard(type,label,icon,time){if(state.removedMeals.includes(type))return `<div class="card" style="margin:9px 0"><div class="meal-card"><span class="food-icon">＋</span><div class="meal-card-main"><div class="meal-tag">${label}</div><h3>Removed from this draft</h3><div class="meal-actions"><button data-action="restore-meal" data-value="${type}">Add a meal back</button></div></div></div></div>`;return `<div class="card" style="margin:9px 0"><div class="meal-card"><span class="food-icon">${icon}</span><div class="meal-card-main"><div class="meal-tag">${label} · ${time}</div><h3>${esc(mealName(type))}</h3><p>${mealIngredients(type)}</p><div class="portion-control"><span>Servings</span><div><button data-action="portion-change" data-meal="${type}" data-value="-1" aria-label="Decrease ${label} servings" ${state.servings[type]===1?'disabled':''}>−</button><strong>${state.servings[type]}</strong><button data-action="portion-change" data-meal="${type}" data-value="1" aria-label="Increase ${label} servings" ${state.servings[type]===4?'disabled':''}>＋</button></div></div><div class="meal-actions"><button data-action="swap" data-value="${type}">Swap</button><button data-action="remove-meal" data-value="${type}">Remove</button><button data-action="recipe" data-value="${type}">Recipe</button></div></div></div></div>`}
function planScreen(){
  if(pausedSafety())return wrap(`${header('Your plan')}<h1 class="page-title">A food detail is paused.</h1><p class="subtext">Review the paused detail before using a meal plan.</p><button class="primary full" data-action="memory" style="margin-top:20px">Review memory</button>`,'plan');
  if(needsVerifiedRecipes()||needsHealthReview()||planNeedsAdjustment())return planningHold();
  const dates=planDates.map(date=>`${date.toLocaleDateString('en',{weekday:'short'})} ${date.getDate()}`);
  const cards=plannedTypes().map(type=>mealCard(type,mealLabel(type),({breakfast:'🥣',lunch:'🥗',dinner:'🍲'})[type],({breakfast:'7–9 AM',lunch:'12–2 PM',dinner:'7–9 PM'})[type])).join('');
  const stale=basketNeedsRefresh();
  return wrap(`${header('Your plan')}<span class="eyebrow-small">DRAFT · NOT ORDERED</span><h1 class="page-title" style="margin-top:8px">Review your meals.</h1><p class="subtext">Five-day illustrative plan · ${esc(state.mealsToPlan.toLowerCase())} · one person.</p><div class="day-tabs">${dates.map((date,i)=>`<button class="day-tab ${state.day===i?'active':''}" data-action="day" data-value="${i}">${date.split(' ')[0]}<strong>${date.split(' ')[1]}</strong></button>`).join('')}</div><div class="plan-summary">${chip('~25 min active time')}${chip(stale?'New quote needed':'₹640 example estimate','amber')}</div>${cards}${stale?`<div class="coverage-note"><strong>Ingredient checklist updated</strong><p>${basketRefreshReason()} Quantities and prices need a fresh calculation before ordering.</p></div>`:''}<div class="rotation"><p>Want another direction? Change this draft by voice or text.</p><div class="rotation-options"><button data-action="rotate" data-value="italian">Something Italian</button><button data-action="rotate" data-value="quick">Simple & quick</button><button data-action="rotate" data-value="different">Something different</button></div></div><div class="button-row"><button class="secondary" data-action="prepared">Order a meal instead</button><button class="primary" data-action="${stale?'draft-ingredients':'accept-plan'}">${stale?'Review ingredients':'Review groceries'}</button></div>`, 'plan');
}
function shop(){if(!state.planAccepted||basketNeedsRefresh())return wrap(`${header('Groceries')}<h1 class="page-title">Review the draft first.</h1><p class="subtext">The grocery estimate needs to match your current meals and pantry.</p><button class="primary full" data-action="nav" data-screen="plan" style="margin-top:22px">Back to plan</button>`, 'plan');return wrap(`${header('Groceries')}<span class="eyebrow-small">EXAMPLE · NO LIVE QUOTES</span><h1 class="page-title" style="margin-top:8px">Your grocery options.</h1><p class="subtext">Compare the full example price, then review the exact basket before any approval.</p><div class="section-row"><h2 class="section-title">From your pantry</h2><button class="text-link" data-action="pantry">Manage</button></div><div class="card">${state.pantry.map(x=>basketRow(x.icon,x.name,x.qty)).join('')}</div><div class="section-row"><h2 class="section-title">To buy</h2>${chip('5 items')}</div><div class="card">${[['🥣','Rolled oats','500 g'],['🥛',state.pattern==='Vegan'?'Plant yogurt':'Plain yogurt','400 g'],['🍌','Bananas','3 pcs'],['🥒','Cucumber','1 pc'],['🥬','Mixed vegetables','500 g']].map(x=>basketRow(...x)).join('')}</div><div class="section-row"><h2 class="section-title">Illustrative offers</h2><span class="eyebrow-small">NOT LIVE</span></div>${merchant(0,'Market Basket','Tomorrow, 8–10 AM','₹640')}${merchant(1,'Quick Cart','Tonight, 9–10 PM','₹688')}<div class="disclosure">Prices and availability here demonstrate the approval design. The real app will request live quotes and show all fees before purchase.</div><button class="primary full" data-action="basket-review">Review exact basket →</button>`, 'plan')}
function basketRow(icon,name,qty){return `<div class="basket-row"><span class="item-symbol">${icon}</span><div><strong>${esc(name)}</strong></div><span class="qty">${esc(qty)}</span></div>`}
function merchant(i,name,slot,price){return `<button class="card merchant ${state.selectedMerchant===i?'selected-merchant':''}" data-action="merchant" data-value="${i}" style="width:100%;text-align:left;margin-bottom:9px"><span class="radio"></span><span style="flex:1"><strong>${name}</strong><small>${slot} · includes fees</small></span><span class="merchant-price">${price}</span></button>`}
function insights(){const count=state.consumed.length;return wrap(`${header('Insights')}<span class="eyebrow-small">YOUR CHECK-INS</span><h1 class="page-title" style="margin-top:8px">A clearer picture, over time.</h1><p class="subtext">Only meals you confirm appear here. Missing meals stay unknown.</p><div class="metric-grid" style="margin-top:22px"><div class="metric"><span>Meals confirmed</span><strong>${count}</strong><span>From your check-ins</span></div><div class="metric"><span>Plans accepted</span><strong>${state.planAccepted?'1':'0'}</strong><span>Example draft</span></div></div><div class="coverage-note"><strong>Coverage is still partial</strong><p>${count?'These entries show what you reported, not everything you ate.':'No meals confirmed yet. Start with any meal you remember.'}</p></div><div class="section-row"><h2 class="section-title">Meals you reported</h2><button class="text-link" data-action="log-meal">Add a meal</button></div><div class="card">${count?state.consumed.slice().reverse().map(x=>`<div class="confirmed-meal"><span class="food-icon">✓</span><div><strong>${esc(x.meal)}</strong><small>${esc(x.portion)} · ${x.source?`linked to ${esc(x.sourceKind.toLowerCase())}: ${esc(x.source)}`:'reported by you'}</small></div></div>`).join(''):'<div class="empty-state">Your confirmed meals will appear here after a check-in.</div>'}</div><div class="section-row"><h2 class="section-title">Not enough data yet</h2></div><div class="card"><p class="subtext">Spend, variety, and nutrient estimates need more reliable meal or order records. Valora won’t turn an incomplete log into a health score.</p></div>`, 'insights')}
function you(){return wrap(`${header('You','settings')}<div class="profile-hero card"><div class="avatar">Y</div><div><span class="eyebrow-small">YOUR PROFILE</span><h1>Food that fits you.</h1><p>Review what Valora uses when shaping a plan.</p></div></div><div class="section-row"><h2 class="section-title">Food rules</h2><button class="text-link" data-action="profile-rules">Edit</button></div><div class="card profile-section">${summaryRow('Eating pattern',state.pattern)}${summaryRow('Foods you don’t eat',state.neverEat.trim()||'None added')}${summaryRow('Allergies',state.allergies.length?selectedWithOther('allergies','otherAllergy'):'None reported')}${summaryRow('Health context',state.health.length?selectedWithOther('health','otherHealth'):'Not shared')}<p class="profile-note">Reported by you · change anything that no longer applies.</p></div><div class="section-row"><h2 class="section-title">Everyday preferences</h2><button class="text-link" data-action="profile-practical">Edit</button></div><div class="card profile-section">${summaryRow('Main goal',selectedWithOther('goal','otherGoal'))}${summaryRow('Meals to plan',state.mealsToPlan)}${summaryRow('Weekly grocery limit',`${rupees(state.budgetAmount)} / week`)}${summaryRow('Cooking time',`Up to ${state.timeMinutes} min`)}${summaryRow('Cuisines',selectedWithOther('cuisines','otherCuisine'))}${summaryRow('Plan reminder',state.notificationTime)}</div><div class="section-row"><h2 class="section-title">Your information</h2></div><div class="card profile-links">${listRow('▤','Reports & photos','Review proposed facts before saving','reports')}${listRow('◉','Memory & corrections','See the facts Valora can use','memory')}${listRow('♧','Pantry & leftovers','Update what is available','pantry')}${listRow('◷','Notifications','Timing and frequency','settings')}${listRow('⊘','Privacy & permissions','How your information is handled','privacy')}${listRow('▣','Payment methods','No method connected','payments')}</div>`, 'you')}
function listRow(icon,title,desc,action){return `<button class="list-row" data-action="${action}" style="width:100%;border-left:0;border-right:0;border-top:0;background:none;text-align:left"><span class="row-icon">${icon}</span><span><strong>${title}</strong><small>${desc}</small></span><span class="arrow">›</span></button>`}
function notificationCard(number,label,title,description,action,route,value=''){return `<section class="notification-card"><div class="notification-index">${number}</div><div class="notification-content"><span>${label}</span><h3>${title}</h3><p>${description}</p><button data-action="${route}" ${value?`data-screen="${value}"`:''}>${action} <span aria-hidden="true">↗</span></button></div></section>`}
const memoryEntries = () => [
  ['neverEat','Foods you don’t eat',state.neverEat.trim()],
  ...['allergies','health','goal','cuisines'].flatMap(group=>state[group].filter(value=>value!=='None'&&value!=='Prefer not to say').map(value=>[`${group}:${encodeURIComponent(value)}`,({allergies:'Reported allergy',health:'Health context',goal:'Goal',cuisines:'Cuisine you enjoy'})[group],value==='Other'?state[({allergies:'otherAllergy',health:'otherHealth',goal:'otherGoal',cuisines:'otherCuisine'})[group]]||'Other':value]))
].filter(([, ,value])=>value);
function memorySheet(){return `<h2>What Valora remembers</h2><p>Inspect, pause, or remove a detail. Paused food safety details stop this example plan until you review them.</p>${memoryEntries().length?memoryEntries().map(([key,label,value])=>`<div class="memory-group"><span>${state.pausedFacts.includes(key)?'PAUSED':'REPORTED BY YOU'}</span><h3>${esc(label)}</h3><p>${esc(value)}</p><div class="memory-actions"><button class="secondary" data-action="memory-detail" data-value="${key}">Inspect</button><button class="secondary" data-action="memory-pause" data-value="${key}">${state.pausedFacts.includes(key)?'Resume':'Pause'}</button><button class="text-link" data-action="memory-remove" data-value="${key}">Remove</button></div></div>`).join(''):'<div class="card empty-state">No optional details saved.</div>'}<div class="memory-group"><span>PLANNING SETTINGS</span>${summaryRow('Eating pattern',state.pattern)}${summaryRow('Meals to plan',state.mealsToPlan)}${summaryRow('Budget',`${rupees(state.budgetAmount)} / week`)}${summaryRow('Cooking time',`${state.timeMinutes} min`)}<button class="secondary full" data-action="profile-practical">Change planning settings</button></div>`}
function memoryDetailSheet(){const entry=memoryEntries().find(([key])=>key===state.memoryKey);if(!entry)return memorySheet();const [key,label,value]=entry;const source=state.factSources[key]||'Reported by you';return `<h2>${esc(label)}</h2><p>Review the saved value and its source before changing it.</p><div class="card">${summaryRow('Value',value)}${summaryRow('Status',state.pausedFacts.includes(key)?'Paused':'Active')}${summaryRow('Source',source)}</div><div class="button-row"><button class="secondary" data-action="memory">Back</button><button class="primary" data-action="${['goal','cuisines'].includes(key.split(':')[0])?'profile-practical':'profile-rules'}">Correct detail</button></div><div class="memory-actions"><button class="secondary" data-action="memory-pause" data-value="${key}">${state.pausedFacts.includes(key)?'Resume':'Pause'} detail</button><button class="text-link" data-action="memory-remove" data-value="${key}">Remove detail</button></div>`}
function settingsSheet(){return `<h2>Notifications</h2><p>Choose which routine prompts Valora may send. This preview does not schedule real notifications.</p><div class="card"><div class="list-row"><strong>Routine notifications</strong><button class="setting-toggle ${state.notifications?'on':''}" data-action="toggle-notifications" role="switch" aria-checked="${state.notifications}" aria-label="Routine notifications"></button></div><label class="field-label">Best time for a plan</label><div class="segmented">${['Morning','Evening'].map(x=>`<button data-action="single" data-group="notificationTime" data-value="${x}" class="${state.notificationTime===x?'active':''}">${x}</button>`).join('')}</div><label class="field-label">Prompt categories</label>${choices('notificationCategories',['Plan ready','Pantry check','Meal check-in'],state.notificationCategories)}<label class="field-label" for="notification-frequency">Frequency</label><select class="input" id="notification-frequency" data-setting="notificationFrequency">${['Daily','A few times a week','Weekly'].map(x=>`<option ${state.notificationFrequency===x?'selected':''}>${x}</option>`).join('')}</select><div class="quiet-grid"><div><label class="field-label" for="quiet-start">Quiet hours start</label><input class="input" type="time" id="quiet-start" data-setting="quietStart" value="${state.quietStart}"/></div><div><label class="field-label" for="quiet-end">End</label><input class="input" type="time" id="quiet-end" data-setting="quietEnd" value="${state.quietEnd}"/></div></div>${summaryRow('Health details on lock screen','Hidden')}</div><button class="primary full" data-action="save-settings" style="margin-top:16px">Done</button>`}
function notificationsSheet(){const previews=[];if(state.notifications){if(state.notificationCategories.includes('Plan ready'))previews.push(notificationCard('01','PLAN READY','Tomorrow’s plan is ready','Review meals before deciding.','Review plan','nav','plan'));if(state.notificationCategories.includes('Pantry check'))previews.push(notificationCard('02','PANTRY CHECK','Still have chickpeas?','Correct your pantry estimate.','Check pantry','pantry'));if(state.notificationCategories.includes('Meal check-in'))previews.push(notificationCard('03','MEAL CHECK-IN','Did you have that meal?','Confirm only what you ate.','Confirm a meal','log-meal'))}return `<h2>Your check-ins</h2><p>Examples based on your routine settings. No push is scheduled in this preview.</p><div class="notification-preview"><span>LOCK SCREEN PREVIEW</span><strong>Valora has something for you</strong><small>Health details stay hidden.</small></div>${previews.join('')||'<div class="card empty-state">Routine prompts are off. Turn on a category in settings to preview it here.</div>'}<div class="notification-footer"><button class="secondary" data-action="close">Close</button><button class="primary" data-action="settings">Notification settings</button></div>`}
function practicalSheet(){return `<h2>Everyday preferences</h2><p>Set the meals, time, and spending limits you want a plan to respect.</p><label class="field-label" for="meals-select">Meals to plan</label><select class="input" id="meals-select">${['Breakfast, lunch & dinner','Lunch & dinner','Dinner only'].map(x=>`<option ${state.mealsToPlan===x?'selected':''}>${x}</option>`).join('')}</select>${rangeControl('budgetAmount','Weekly grocery budget',500,15000,250,state.budgetAmount,`${rupees(state.budgetAmount)} / week`)}${rangeControl('timeMinutes','Max cooking time per meal',5,120,5,state.timeMinutes,`${state.timeMinutes} min`)}<label class="field-label">Cuisines you enjoy</label>${choices('cuisines',['Indian','Italian','Asian','Mediterranean','Mexican','Anything','Other'],state.cuisines)}${otherField('cuisines','otherCuisine','Which cuisine?','e.g. Korean')}<button class="primary full" data-action="close" style="margin-top:18px">Done</button>`}
function logSheet(){return `<h2>What did you eat?</h2><p>Only a meal you confirm appears in Insights.</p><label class="field-label" for="meal-name">Meal or food</label><input class="input" id="meal-name" value="${esc(state.logMealName||mealName(activeTypes()[0]||'dinner'))}"/><label class="field-label" for="portion">How much?</label><select class="input" id="portion"><option>About 1 serving</option><option>About half a serving</option><option>About 2 servings</option><option>I'm not sure</option></select><label class="field-label" for="log-source">Where did it come from?</label><select class="input" id="log-source"><option value="">Somewhere else or not sure</option>${state.pantry.map((item,i)=>`<option value="${i}">${esc(item.kind==='Leftover'?'Leftover':'Pantry')}: ${esc(item.name)} (${esc(item.qty)})</option>`).join('')}</select><div id="log-source-fields"></div><p class="inline-note">Reporting a meal never changes pantry stock by itself.</p><div class="button-row"><button class="secondary" data-action="close">Cancel</button><button class="primary" data-action="confirm-meal">Confirm meal</button></div>`}
function renderLogSourceFields(){const target=$('#log-source-fields');if(!target)return;const item=state.pantry[Number($('#log-source')?.value)];target.innerHTML=$('#log-source')?.value===''?'':`<label class="field-label" for="remaining-qty">How much ${esc(item.name)} is left now? (optional)</label><input class="input" id="remaining-qty" placeholder="Currently ${esc(item.qty)}"/><p class="inline-note">Enter the remaining amount yourself. Valora won’t guess a conversion or subtract it twice.</p>`}
function draftIngredientsSheet(){return `<h2>Ingredients for this draft</h2><p>Based on the visible meals for ${planDates[state.day].toLocaleDateString('en',{weekday:'long',month:'short',day:'numeric'})}. Serving counts are shown, but exact quantities and provider prices need a new calculation.</p><div class="card">${activeTypes().map(type=>summaryRow(`${mealLabel(type)} · ${state.servings[type]} ${state.servings[type]===1?'serving':'servings'}`,mealName(type))).join('')}</div><div class="section-row"><h3 class="section-title">Ingredient checklist</h3></div><div class="card">${draftIngredients().map(item=>`<div class="list-row"><strong>${esc(item)}</strong></div>`).join('')||'<p>No meals selected.</p>'}</div><div class="coverage-note"><strong>Quote needed</strong><p>Pantry amounts, packages, and prices must be recalculated before showing offers or asking for order approval.</p></div><button class="primary full" data-action="close">Back to plan</button>`}
const preparedOffers = () => {
  const preferredCuisine=state.cuisines.find(x=>!['Anything','Other'].includes(x))||'Indian';
  const offers=[
    {dish:preferredCuisine==='Italian'?'Roasted vegetable pasta bowl':preferredCuisine==='Asian'?'Tofu and vegetable rice bowl':'Paneer rice bowl',restaurant:preferredCuisine==='Italian'?'Little Basil Kitchen':preferredCuisine==='Asian'?'Green Wok':'Saffron Table',cuisine:preferredCuisine,price:279,fee:30,eta:'30–40 min',fit:'Closest match to your cuisine choice',icon:'🍲',ingredients:preferredCuisine==='Italian'?'Pasta, roasted vegetables, tomato sauce':preferredCuisine==='Asian'?'Rice, tofu, mixed vegetables, soy sauce':'Rice, paneer, tomato, spices'},
    {dish:state.pattern==='Vegan'?'Chickpea and grain bowl':'Seasonal vegetable grain bowl',restaurant:'Harvest Bowl Co.',cuisine:'Mediterranean',price:249,fee:25,eta:'25–35 min',fit:'Lighter vegetable-forward option',icon:'🥗',ingredients:'Whole grains, chickpeas, seasonal vegetables, dressing'},
    {dish:'Dal, rice and seasonal vegetables',restaurant:'Everyday Kitchen',cuisine:'Indian',price:219,fee:20,eta:'35–45 min',fit:'Lowest example total',icon:'🍛',ingredients:'Lentils, rice, seasonal vegetables, spices'}
  ];
  if(state.pattern==='Vegan')offers[0]={dish:'Tofu and vegetable rice bowl',restaurant:'Green Wok',cuisine:'Asian',price:269,fee:25,eta:'30–40 min',fit:'Plant-based example option',icon:'🥘',ingredients:'Rice, tofu, mixed vegetables, soy sauce'};
  return offers;
};
function preparedSheet(){
  if(needsVerifiedRecipes()||needsHealthReview()||pausedSafety())return `<h2>Food delivery options</h2><p>Review your food details before showing dishes. This preview cannot verify restaurant ingredients or preparation.</p><div class="coverage-note"><strong>Options held for review</strong><p>${needsVerifiedRecipes()?'Reported allergies or food exclusions need verified menu and cross-contact information.':'Your shared health context needs an appropriate review before a dish can be ranked.'}</p></div><div class="button-row"><button class="secondary" data-action="close">Back to plan</button><button class="primary" data-action="${pausedSafety()?'memory':'profile-rules'}">Review details</button></div>`;
  const offers=preparedOffers(),selected=offers[state.selectedPrepared]||offers[0];
  if(state.preparedReview)return `<h2>Review this meal</h2><p>Check the selected dish and example delivery total before continuing.</p><div class="card prepared-review-card"><div class="prepared-dish-icon">${selected.icon}</div><span class="eyebrow-small">SAMPLE OFFER · NOT LIVE</span><h3>${esc(selected.dish)}</h3><p>${esc(selected.restaurant)} · ${esc(selected.cuisine)} · ${selected.eta}</p><div class="focus-divider"></div>${summaryRow('Menu description',selected.ingredients)}${summaryRow('Food-rule check','Not verified')}${summaryRow('Items subtotal',rupees(selected.price))}${summaryRow('Delivery & fees',rupees(selected.fee))}<div class="price-line total"><span>Example total</span><span>${rupees(selected.price+selected.fee)}</span></div></div><div class="disclosure">Sample details only. The restaurant, menu, ingredients, allergen handling, availability, and price are not connected or verified. No order can be placed from this preview.</div><div class="button-row"><button class="secondary" data-action="prepared-back">Choose another</button><button class="primary" data-action="prepared-demo-order">Continue to order</button></div>`;
  return `<h2>Order a meal instead</h2><p>Best match for your plan, cuisine, and food preferences.</p><div class="prepared-rank-label"><span>BEST MATCH</span><small>Ranked for cuisine fit, delivery time & total cost</small></div>${offers.map((offer,i)=>`<button class="card prepared-offer ${state.selectedPrepared===i?'selected-prepared':''}" data-action="prepared-select" data-value="${i}" aria-pressed="${state.selectedPrepared===i}"><span class="prepared-dish-icon">${offer.icon}</span><span class="prepared-offer-main"><span class="prepared-offer-top"><strong>${esc(offer.dish)}</strong>${i===0?'<em>Best match</em>':''}</span><small>${esc(offer.restaurant)} · ${esc(offer.cuisine)}</small><small>${esc(offer.fit)}</small><span class="prepared-offer-bottom"><span>${offer.eta} · ${rupees(offer.price)} + ${rupees(offer.fee)} delivery</span><b>${rupees(offer.price+offer.fee)}</b></span></span></button>`).join('')}<div class="coverage-note"><strong>Sample offers · no live provider connected</strong><p>Real ranking needs current menus, ingredient and allergen details, portions, availability, delivery distance, ratings, and full fees. This example cannot confirm food-rule suitability.</p></div><button class="primary full" data-action="prepared-review">Review selected meal →</button><button class="text-link full" data-action="close" style="margin-top:10px">Back to meal plan</button>`
}
function pantrySheet(){return `<h2>Pantry & leftovers</h2><p>Estimated amounts at home. A reported meal changes an amount only if you confirm what remains.</p><div class="pantry-summary">${state.pantry.length} items listed <span>Tap an item to correct it</span></div><div class="card">${state.pantry.length?state.pantry.map((item,i)=>`<button class="pantry-item" data-action="pantry-edit" data-value="${i}"><span class="item-symbol">${item.icon}</span><span><strong>${esc(item.name)}</strong><small>${esc(item.kind||'Ingredient')} · ${esc(item.qty)} estimated</small></span><span class="arrow">Edit ›</span></button>`).join(''):'<div class="empty-state">No items listed. Add an ingredient or prepared leftover.</div>'}</div><div class="button-row"><button class="secondary" data-action="close">Done</button><button class="primary" data-action="pantry-add">Add item</button></div>`}
function startVoiceCapture(){const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){notify('Voice input is unavailable in this browser. Type your request below.');return}try{const recognition=new Recognition();recognition.lang=navigator.language||'en-IN';recognition.interimResults=false;recognition.maxAlternatives=1;recognition.onresult=event=>{const spoken=event.results?.[0]?.[0]?.transcript||'';const input=$('#chat-input');if(input){input.value=spoken;input.focus()}state.toast='Voice captured. Review the text before sending.';const toast=document.createElement('div');toast.className='toast';toast.setAttribute('role','status');toast.textContent=state.toast;$('#app').append(toast);setTimeout(()=>toast.remove(),3000)};recognition.onerror=()=>notify('Voice capture was unavailable. You can type your request.');recognition.start();notify('Listening… speak your request.')}catch{notify('Voice capture could not start in this browser.')}}
function reportsSheet(){return `<h2>Reports & photos</h2><p>A file picker is available, but extraction is not connected in this preview. No file bytes or facts are saved.</p><label class="upload-zone" for="report-file"><strong>Choose a PDF or image</strong><small>PDF, JPG or PNG</small></label><input id="report-file" type="file" accept=".pdf,image/jpeg,image/png"/><p id="file-status" class="inline-note">No file selected</p><div class="card"><strong>Fact review example</strong><p>Preview a sample proposed allergy fact to see the confirmation step.</p><button class="secondary full" data-action="demo-upload">Preview sample review</button></div>`}
function sheet(){if(!state.sheet)return '';let body='';switch(state.sheet){
case 'notifications':body=notificationsSheet();break;
case 'settings':body=settingsSheet();break;
case 'basket':body=`<h2>Review before ordering</h2><p>This is a design example. No provider or payment is connected.</p><div class="card">${summaryRow('Merchant',state.selectedMerchant?'Quick Cart':'Market Basket')}${summaryRow('Rolled oats','500 g')}${summaryRow(state.pattern==='Vegan'?'Plant yogurt':'Plain yogurt','400 g')}${summaryRow('Bananas','3 pcs')}${summaryRow('Cucumber','1 pc')}${summaryRow('Mixed vegetables','500 g')}${summaryRow('Delivery',state.selectedMerchant?'Tonight, 9–10 PM':'Tomorrow, 8–10 AM')}${summaryRow('Substitutions','Ask me first')}${summaryRow('Items subtotal',state.selectedMerchant?'₹620':'₹580')}${summaryRow('Delivery + fees',state.selectedMerchant?'₹68':'₹60')}<div class="price-line total"><span>Total to approve</span><span>${state.selectedMerchant?'₹688':'₹640'}</span></div></div><div class="disclosure">In the real app, this button will authorize only this merchant, basket, delivery window, and maximum total. Any change will require new approval.</div><div class="button-row"><button class="secondary" data-action="close">Back</button><button class="primary" data-action="demo-approval">Approve example</button></div>`;break;
case 'recipe':body=`<h2>${esc(mealName(state.recipeType||'lunch'))}</h2><p>${state.servings[state.recipeType||'lunch']} ${state.servings[state.recipeType||'lunch']===1?'serving':'servings'} · about 25 minutes · illustrative recipe</p><div class="card"><strong style="font-size:12px">Ingredients</strong><p>${mealIngredients(state.recipeType||'lunch')}. Check exact ingredients before preparing.</p><strong style="font-size:12px">Simple method</strong><p>Prepare the base, add the vegetables or fruit, then season to taste.</p></div><div class="button-row"><button class="secondary" data-action="close">Close</button><button class="primary" data-action="log-meal">I ate this</button></div>`;break;
case 'log':body=logSheet();break;
case 'reports':body=reportsSheet();break;
case 'fact-review':body=`<h2>Review a proposed fact</h2><p>Sample only · no file was processed. Review the meaning before saving.</p><div class="card"><span class="eyebrow-small">PROPOSED, NOT SAVED</span><p>Sample source, page 1: “Avoid peanuts.”</p><label class="field-label" for="fact-kind">Save this as</label><select class="input" id="fact-kind"><option>Food exclusion</option><option>Reported allergy</option><option>Health context</option></select><label class="field-label" for="fact-value">Detail</label><input class="input" id="fact-value" value="Peanuts"/></div><div class="button-row"><button class="secondary" data-action="reject-fact">Reject</button><button class="primary" data-action="confirm-fact">Confirm & save</button></div>`;break;
case 'pantry':body=pantrySheet();break;
 case 'pantry-add':body=`<h2>Add pantry item</h2><p>Record an estimate; you can correct it later.</p><label class="field-label" for="pantry-kind">What is it?</label><select class="input" id="pantry-kind"><option>Ingredient</option><option>Leftover</option></select><label class="field-label" for="pantry-name">Item</label><input class="input" id="pantry-name" placeholder="e.g. Tomatoes or cooked rice"/><label class="field-label" for="pantry-qty">Amount</label><input class="input" id="pantry-qty" placeholder="e.g. 3 pieces or 2 portions"/><div class="button-row"><button class="secondary" data-action="pantry">Back</button><button class="primary" data-action="save-pantry">Save item</button></div>`;break;
case 'pantry-edit':{const item=state.pantry[state.pantryIndex];body=item?`<h2>Correct pantry item</h2><p>Update the amount you believe is still available.</p><label class="field-label" for="pantry-name">Item</label><input class="input" id="pantry-name" value="${esc(item.name)}"/><label class="field-label" for="pantry-qty">Amount left</label><input class="input" id="pantry-qty" value="${esc(item.qty)}"/><button class="text-link pantry-remove" data-action="pantry-remove">Remove from pantry</button><div class="button-row"><button class="secondary" data-action="pantry">Back</button><button class="primary" data-action="save-pantry-edit">Save correction</button></div>`:'<h2>Item unavailable</h2><button class="primary full" data-action="pantry">Back to pantry</button>';break}
case 'profile-rules':body=`<h2>Food rules</h2><p>These details shape which meals can be shown. Changes update this preview immediately.</p><label class="field-label">Eating pattern</label><div class="segmented">${['Omnivore','Vegetarian','Vegan'].map(x=>`<button data-action="single" data-group="pattern" data-value="${x}" class="${state.pattern===x?'active':''}">${x}</button>`).join('')}</div>${detailField('neverEat','Foods you don’t eat','e.g. beef, pork, mushrooms')}<label class="field-label">Allergies you reported</label>${choices('allergies',['Peanuts','Tree nuts','Milk','Eggs','Wheat','Other'],state.allergies)}${otherField('allergies','otherAllergy','Which allergy?','e.g. sesame')}<label class="field-label">Health context (optional)</label>${choices('health',['None','Diabetes','High blood pressure','Digestive issue','Recent injury','Other','Prefer not to say'],state.health)}${otherField('health','otherHealth','Tell us only what you want to share','e.g. a recent injury')}<button class="primary full" data-action="close" style="margin-top:18px">Done</button>`;break;
case 'profile-practical':body=practicalSheet();break;
case 'memory':body=memorySheet();break;
case 'privacy':body=`<h2>Privacy & control</h2><p>Your information should be easy to inspect and correct.</p><div class="card">${listRow('▤','Reports & photos','Original files are discarded after fact review','reports')}${listRow('◉','Saved facts','Review and correct what Valora may use','memory')}${listRow('♧','Notifications','Health details stay off lock-screen previews','settings')}</div><div class="coverage-note"><strong>In this design preview</strong><p>Changes live only in this browser session. No account, cloud storage, or purchase connection is active.</p></div><button class="primary full" data-action="close" style="margin-top:15px">Done</button>`;break;
case 'payments':body=`<h2>Payment methods</h2><p>Payment credentials will be managed by a payment provider. Valora will never store raw card details or purchase without a reviewed approval.</p><div class="card"><strong style="font-size:12px">No payment method connected</strong><p>Add one in the real app when a supported merchant integration is available.</p></div><button class="primary full" data-action="close" style="margin-top:15px">Done</button>`;break;
case 'prepared':body=preparedSheet();break;
case 'memory-detail':body=memoryDetailSheet();break;
case 'draft-ingredients':body=draftIngredientsSheet();break;
default:body=`<h2>Coming into focus</h2><p>This part of the experience is represented in the screen flow.</p><button class="primary full" data-action="close">Close</button>`}
 body=body.replace('<h2>','<h2 id="sheet-title" tabindex="-1">');
 return `<div class="overlay" data-action="close-overlay"><div class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title"><div class="sheet-handle"></div><button class="sheet-close" data-action="close" aria-label="Close dialog">×</button>${body}</div></div>`}
let renderedScreen = null;
let renderedSheet = null;
function render(){
  const memoryKeys=new Set(memoryEntries().map(([key])=>key));
  state.pausedFacts=state.pausedFacts.filter(key=>memoryKeys.has(key));
  for(const key of Object.keys(state.factSources))if(!memoryKeys.has(key))delete state.factSources[key];
  const chatDraft=$('#chat-input')?.value||'';
  const previousScroll = renderedScreen===state.screen ? $('#app .screen')?.scrollTop ?? 0 : 0;
  const sheetChanged=renderedSheet!==state.sheet;
  const previousSheet = !sheetChanged&&state.sheet ? $('#app .sheet')?.scrollTop ?? 0 : 0;
  const content=({onboarding,summary:profileSummary,chat,plan:planScreen,shop,insights,you}[state.screen]||chat)();
  $('#app').innerHTML=content+sheet()+(state.toast?`<div class="toast" role="status">${esc(state.toast)}</div>`:'');
  if($('#chat-input'))$('#chat-input').value=chatDraft;
  $('#app .screen').scrollTop=previousScroll;
  if(state.sheet&&$('#app .sheet'))$('#app .sheet').scrollTop=previousSheet;
  if(state.sheet&&sheetChanged)$('#sheet-title')?.focus({preventScroll:true});
  renderedScreen=state.screen;
  renderedSheet=state.sheet;
  if(state.toast){setTimeout(()=>{state.toast='';$('.toast')?.remove()},3000)}
}
function showChatResult(){const screen=$('#app .screen');if(!screen)return;if(state.chatView==='ask'){screen.scrollTop=screen.scrollHeight;return}const card=$('#app .request-card')||$('#app .focus-card');if(card)screen.scrollTop=card.offsetTop-screen.offsetTop-16}
function routeChatRequest(request){
  const text=request.toLowerCase();
  state.chatRequest=request;
  const agentRequest = /\b(add|remove|update|change|set|save|remember|forget|calculate|compute|create|make|generate|suggest|recommend|help me)\b/.test(text) || /^(i am|i'm|i have|i don't|i do not)\b/.test(text);
  if(agentRequest){state.chatView='ask';state.chatTurns.push(request);return}
  if(/\b(pantry|fridge|left in (my )?(kitchen|home)|ingredients (i|we) have)\b/.test(text)){state.chatView='pantry';return}
  if(/allerg|food rules|foods? (i|we) (don.t|do not) eat|restriction/.test(text)){state.chatView='allergies';return}
  if(/\b(budget|spend|cooking time|time limit)\b/.test(text)){state.chatView='budget';return}
  if(/\b(why|reason|how come)\b/.test(text)&&/\b(plan|meal|recipe)\b/.test(text)){state.chatView=pausedSafety()||needsVerifiedRecipes()||needsHealthReview()||planNeedsAdjustment()||basketNeedsRefresh()?'plan':'rationale';return}
  if(/italian|something different|another option|simple and quick|quick meal/.test(text)){state.rotation=/italian/.test(text)?(6-state.day)%5:/quick/.test(text)?(7-state.day)%5:state.rotation+1;state.mealOffsets={};state.removedMeals=[];state.planAccepted=false;state.chatView='plan';return}
  if(/\b(plan|tomorrow|meal plan|next meal|what.*(eat|cook))\b/.test(text)){state.chatView='plan';return}
  state.chatView='ask';state.chatTurns.push(request);
}
function notify(msg){state.toast=msg;render()}
function action(name,el,sourceEvent){const value=el?.dataset.value;switch(name){
case 'choice':{let g=el.dataset.group;let a=state[g];let next=a.includes(value)?a.filter(x=>x!==value):[...a,value];if(g==='health'){if(value==='None'||value==='Prefer not to say')next=[value];else next=next.filter(x=>x!=='None'&&x!=='Prefer not to say')}if(g==='cuisines'){if(value==='Anything')next=['Anything'];else next=next.filter(x=>x!=='Anything')}state[g]=next;const otherKey={goal:'otherGoal',allergies:'otherAllergy',health:'otherHealth',cuisines:'otherCuisine'}[g];if(otherKey&&!next.includes('Other'))state[otherKey]='';if(g==='allergies'||g==='health'||g==='goal'||g==='cuisines')state.planAccepted=false;if(state.screen!=='onboarding'&&(g==='goal'||g==='cuisines'))state.planInputsChanged=true;render();break}
case 'single':state[el.dataset.group]=value;if(el.dataset.group==='pattern'){state.planAccepted=false;if(state.screen!=='onboarding')state.planInputsChanged=true}render();break;
case 'finish-onboarding':{state.consent=$('#consent')?.checked||false;if(!state.consent){notify('Please review the acknowledgement first.');break}const missing=[['goal','otherGoal'],['allergies','otherAllergy'],['health','otherHealth'],['cuisines','otherCuisine']].find(([g,f])=>state[g].includes('Other')&&!state[f].trim());if(missing){notify('Please fill in the selected “Other” detail.');break}state.screen='summary';render();break}
case 'back-onboarding':state.screen='onboarding';render();break;
case 'start-app':state.screen='chat';render();break;
case 'nav':state.screen=el.dataset.screen;state.sheet=null;render();break;
case 'notifications':case 'settings':case 'basket-review':case 'prepared':case 'recipe':case 'pantry':case 'pantry-add':case 'reports':case 'memory':case 'privacy':case 'payments':case 'profile-rules':case 'profile-practical':case 'draft-ingredients':if(name==='prepared')state.preparedReview=false;state.sheet=({ 'basket-review':'basket'})[name]||name;if(name==='recipe')state.recipeType=value;render();break;
case 'log-meal':state.logMealName=state.sheet==='recipe'?mealName(state.recipeType||'lunch'):'';state.sheet='log';render();break;
case 'close':state.sheet=null;render();break;
case 'close-overlay':if(el===sourceEvent?.target){state.sheet=null;render()}break;
case 'day':{state.dayDrafts[state.day]={rotation:state.rotation,mealOffsets:{...state.mealOffsets},removedMeals:[...state.removedMeals],servings:{...state.servings}};state.day=Number(value);const draft=state.dayDrafts[state.day];state.rotation=draft?.rotation||0;state.mealOffsets={...draft?.mealOffsets};state.removedMeals=[...(draft?.removedMeals||[])];state.servings={...(draft?.servings||{breakfast:1,lunch:1,dinner:1})};state.planAccepted=false;render();break}
case 'portion-change':{const type=el.dataset.meal;const change=Number(value);state.servings[type]=Math.max(1,Math.min(4,state.servings[type]+change));state.planAccepted=false;render();break}
case 'rotate':state.rotation=value==='italian'?(6-state.day)%5:value==='quick'?(7-state.day)%5:state.rotation+1;state.mealOffsets={};state.removedMeals=[];state.planAccepted=false;state.chatView='plan';state.chatRequest='Show a different meal plan';notify('This day’s example draft changed.');break;
case 'swap':state.mealOffsets[value]=(state.mealOffsets[value]||0)+1;state.planAccepted=false;notify(`${mealLabel(value)} changed in this day’s draft.`);break;
case 'remove-meal':state.removedMeals=[...new Set([...state.removedMeals,value])];state.planAccepted=false;notify(`${value[0].toUpperCase()+value.slice(1)} removed from this draft.`);break;
case 'restore-meal':state.removedMeals=state.removedMeals.filter(x=>x!==value);notify('Meal added back to this draft.');break;
case 'accept-plan':if(needsVerifiedRecipes()){notify('Verified ingredient data is needed before planning.');break}if(needsHealthReview()){notify('This draft needs a health-context check before planning.');break}if(planNeedsAdjustment()){notify('This draft needs to fit your budget and cooking time first.');break}if(basketNeedsRefresh()){notify('The grocery estimate needs a refresh before basket review.');break}state.planAccepted=true;state.screen='shop';render();break;
case 'merchant':state.selectedMerchant=Number(value);render();break;
case 'demo-approval':state.sheet=null;notify('Example reviewed. No order or payment was submitted.');break;
case 'prepared-select':state.selectedPrepared=Number(value);render();break;
case 'prepared-review':state.preparedReview=true;render();break;
case 'prepared-back':state.preparedReview=false;render();break;
case 'prepared-demo-order':state.preparedReview=false;state.sheet=null;notify('Sample offer reviewed. No restaurant was contacted and no order was placed.');break;
case 'confirm-meal':{let meal=$('#meal-name')?.value.trim();if(!meal){notify('Add a meal name first.');break}const sourceValue=$('#log-source')?.value;const sourceIndex=sourceValue===''?null:Number(sourceValue);const source=sourceIndex===null?null:state.pantry[sourceIndex];const remaining=$('#remaining-qty')?.value.trim();state.consumed.push({meal,portion:$('#portion')?.value,source:source?.name||'',sourceKind:source?.kind||'Ingredient'});if(source&&remaining){source.qty=remaining;pantryChanged()}state.logMealName='';state.sheet=null;notify(source&&remaining?'Meal and your corrected pantry amount recorded.':'Meal recorded from your confirmation.');break}
case 'voice':startVoiceCapture();break;
case 'chat-widget':state.chatView=value;state.chatRequest='';render();showChatResult();break;
case 'chat-home':state.chatView='plan';state.chatRequest='';render();$('#app .screen').scrollTop=0;break;
case 'chat-prompt':routeChatRequest(value);render();showChatResult();break;
case 'send':{const request=$('#chat-input')?.value.trim();if(!request)return;$('#chat-input').value='';routeChatRequest(request);render();showChatResult();break}
case 'pantry-confirm':if(value==='no'){state.pantry=state.pantry.filter(x=>x.name!=='Chickpeas');pantryChanged()}notify(value==='yes'?'Thanks, chickpeas remain in your pantry estimate.':'Thanks, chickpeas were removed from the pantry estimate.');break;
case 'pantry-edit':state.pantryIndex=Number(value);state.sheet='pantry-edit';render();break;
case 'pantry-remove':if(state.pantryIndex!==null){state.pantry.splice(state.pantryIndex,1);pantryChanged()}state.pantryIndex=null;state.sheet='pantry';notify('Item removed from your pantry estimate.');break;
case 'save-pantry-edit':{const name=$('#pantry-name')?.value.trim(),qty=$('#pantry-qty')?.value.trim();if(!name||!qty){notify('Enter an item and amount.');break}if(state.pantry[state.pantryIndex]){state.pantry[state.pantryIndex]={...state.pantry[state.pantryIndex],name,qty};pantryChanged()}state.pantryIndex=null;state.sheet='pantry';notify('Pantry estimate corrected.');break}
case 'save-pantry':{let name=$('#pantry-name')?.value.trim(),qty=$('#pantry-qty')?.value.trim();if(!name||!qty){notify('Enter an item and amount.');break}state.pantry.push({name,qty,kind:$('#pantry-kind')?.value||'Ingredient',icon:'◌'});pantryChanged();state.sheet='pantry';notify('Pantry estimate updated.');break}
case 'demo-upload':state.sheet='fact-review';render();break;
case 'confirm-fact':{const detail=$('#fact-value')?.value.trim();if(!detail){notify('Enter the detail you want to save.');break}const kind=$('#fact-kind')?.value;let key;if(kind==='Reported allergy'){const item=['Peanuts','Tree nuts','Milk','Eggs','Wheat'].find(x=>x.toLowerCase()===detail.toLowerCase())||'Other';if(!state.allergies.includes(item))state.allergies.push(item);if(item==='Other')state.otherAllergy=detail;key=`allergies:${encodeURIComponent(item)}`}else if(kind==='Health context'){state.health=state.health.filter(x=>x!=='None'&&x!=='Prefer not to say');if(!state.health.includes('Other'))state.health.push('Other');state.otherHealth=detail;key='health:Other'}else{state.neverEat=[state.neverEat.trim(),detail].filter(Boolean).join(', ');key='neverEat'}state.factSources[key]='Sample source · page 1 · confirmed by you';state.planAccepted=false;state.sheet=null;notify('Reviewed sample detail saved in this preview.');break}
case 'reject-fact':state.sheet=null;notify('Proposed fact rejected.');break;
case 'toggle-notifications':state.notifications=!state.notifications;render();break;
case 'memory-detail':state.memoryKey=value;state.sheet='memory-detail';render();break;
case 'memory-pause':state.pausedFacts=state.pausedFacts.includes(value)?state.pausedFacts.filter(x=>x!==value):[...state.pausedFacts,value];state.planAccepted=false;state.planInputsChanged=true;render();break;
case 'memory-remove':{const [group,encoded]=value.split(':');if(['allergies','health','goal','cuisines'].includes(group)){const item=decodeURIComponent(encoded);state[group]=state[group].filter(x=>x!==item);if(item==='Other')state[({allergies:'otherAllergy',health:'otherHealth',goal:'otherGoal',cuisines:'otherCuisine'})[group]]=''}else if(value==='neverEat')state.neverEat='';delete state.factSources[value];state.pausedFacts=state.pausedFacts.filter(x=>x!==value);state.planAccepted=false;state.planInputsChanged=true;state.sheet='memory';render();break}
case 'save-settings':state.sheet=null;notify('Notification preferences saved for this preview.');break;
case 'edit-profile':state.sheet='profile-rules';render();break;
case 'prepared-preview':state.sheet='prepared';render();break;
case 'energy':notify(`Energy check-in: ${value}. Thanks for sharing.`);break;
}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el)action(el.dataset.action,el,e)});
document.addEventListener('change',e=>{if(e.target.id==='consent')state.consent=e.target.checked;if(e.target.id==='meals-select'){state.mealsToPlan=e.target.value;state.planAccepted=false;if(state.screen!=='onboarding')state.planInputsChanged=true}if(e.target.id==='log-source')renderLogSourceFields();if(e.target.id==='report-file'){const selected=Boolean(e.target.files?.length);e.target.value='';const status=$('#file-status');if(status)status.textContent=selected?'File selection closed. No extraction or storage is connected.':'No file selected'}if(e.target.dataset.setting){state[e.target.dataset.setting]=e.target.value}});
document.addEventListener('input',e=>{const slider=e.target.dataset.slider;if(slider){state[slider]=Number(e.target.value);e.target.style.setProperty('--range-progress',`${(state[slider]-Number(e.target.min))/(Number(e.target.max)-Number(e.target.min))*100}%`);document.getElementById(`${slider}-value`).textContent=slider==='budgetAmount'?`${rupees(state[slider])} / week`:`${state[slider]} min`;state.planAccepted=false;return}const field=e.target.dataset.field;if(field){state[field]=e.target.value;if(['neverEat','otherAllergy','otherHealth','otherGoal','otherCuisine'].includes(field))state.planAccepted=false;if(state.screen!=='onboarding'&&['otherGoal','otherCuisine'].includes(field))state.planInputsChanged=true}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='chat-input'){e.preventDefault();action('send')}if(e.key==='Escape'&&state.sheet){state.sheet=null;render()}});
render();
